29	/** Class for tracking active uids for running processes. */
30	final class ActiveUids {
31	
32	    private final ActivityManagerService mService;
33	    private final ActivityManagerGlobalLock mProcLock;
34	
35	    private final boolean mPostChangesToAtm;
36	
37	    @CompositeRWLock({"mService", "mProcLock"})
38	    private final SparseArray<UidRecord> mActiveUids = new SparseArray<>();
39	
40	    ActiveUids(ActivityManagerService service, boolean postChangesToAtm) {
41	        mService = service;
42	        mProcLock = service != null ? service.mProcLock : null;
43	        mPostChangesToAtm = postChangesToAtm;
44	    }
45	
46	    @GuardedBy({"mService", "mProcLock"})
47	    void put(int uid, UidRecord value) {
48	        mActiveUids.put(uid, value);
49	        if (mPostChangesToAtm) {
50	            mService.mAtmInternal.onUidActive(uid, value.getCurProcState());
51	        }
52	    }
53	
54	    @GuardedBy({"mService", "mProcLock"})
55	    void remove(int uid) {
56	        mActiveUids.remove(uid);
57	        if (mPostChangesToAtm) {
58	            mService.mAtmInternal.onUidInactive(uid);
59	        }
60	    }
61	
62	    @GuardedBy({"mService", "mProcLock"})
63	    void clear() {
64	        mActiveUids.clear();
65	        // It is only called for a temporal container with mPostChangesToAtm == false or test case.
66	        // So there is no need to notify activity task manager.
67	    }
68	
69	    @GuardedBy(anyOf = {"mService", "mProcLock"})
70	    UidRecord get(int uid) {
71	        return mActiveUids.get(uid);
72	    }
73	
