94	    @GuardedBy(anyOf = {"mService", "mProcLock"})
95	    boolean dump(final PrintWriter pw, String dumpPackage, int dumpAppId,
96	            String header, boolean needSep) {
97	        boolean printed = false;
98	        for (int i = 0; i < mActiveUids.size(); i++) {
99	            final UidRecord uidRec = mActiveUids.valueAt(i);
100	            if (dumpPackage != null && UserHandle.getAppId(uidRec.getUid()) != dumpAppId) {
101	                continue;
102	            }
103	            if (!printed) {
104	                printed = true;
105	                if (needSep) {
106	                    pw.println();
107	                }
108	                pw.print("  "); pw.println(header);
109	            }
110	            pw.print("    UID "); UserHandle.formatUid(pw, uidRec.getUid());
111	            pw.print(": "); pw.println(uidRec);
112	            pw.print("      curProcState="); pw.print(uidRec.getCurProcState());
113	            pw.print(" curCapability=");
114	            ActivityManager.printCapabilitiesFull(pw, uidRec.getCurCapability());
115	            pw.println();
116	            uidRec.forEachProcess(app -> {
117	                pw.print("      proc=");
118	                pw.println(app);
119	            });
120	        }
121	        return printed;
122	    }
123	
124	    void dumpProto(ProtoOutputStream proto, String dumpPackage, int dumpAppId, long fieldId) {
125	        for (int i = 0; i < mActiveUids.size(); i++) {
126	            UidRecord uidRec = mActiveUids.valueAt(i);
127	            if (dumpPackage != null && UserHandle.getAppId(uidRec.getUid()) != dumpAppId) {
128	                continue;
129	            }
130	            uidRec.dumpDebug(proto, fieldId);
131	        }
132	    }
133	}
