831	            if (parent != null) {
832	                // Send PROFILE_ACCESSIBLE broadcast to the parent user if a profile was unlocked
833	                broadcastProfileAccessibleStateChanged(userId, parent.id,
834	                        Intent.ACTION_PROFILE_ACCESSIBLE);
